#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include <ArduinoJson.h>
#include <Update.h>
#include "NMEAEngine.h"
#include "Settings.h"
#include "GnssLogger.h"
#include "TrackExport.h"
#include "EventEngine.h"

HardwareSerial GNSS(1),GPSOut(2);WebServer web(80);WiFiServer tcp(10110);WiFiClient clients[4];NMEAEngine nmea;SettingsManager settings;GnssLogger logger;EventEngine events;unsigned long packets=0,invalid=0,lastDataMs=0;
String wifiMode="AP";
String page(){return R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>NavIC GPS Bridge</title><style>body{margin:0;font-family:system-ui;background:#08111f;color:#eaf2ff}.top{padding:18px;background:#0d1930;display:flex;justify-content:space-between}.wrap{max-width:1100px;margin:auto;padding:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.card{background:#12223e;border:1px solid #28456f;border-radius:16px;padding:16px}.label{font-size:11px;color:#9bb0da;text-transform:uppercase}.value{font-size:24px;font-weight:bold;margin-top:6px}.ok{color:#62e6a3}.bad{color:#ff7891}.sats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.sat{background:#0c1930;padding:12px;border-radius:12px}.bar{height:6px;background:#263e66;border-radius:5px}.fill{height:100%;background:#64b5ff;border-radius:5px}.actions{display:flex;gap:10px;flex-wrap:wrap}button,a.btn{padding:10px 14px;border-radius:10px;border:1px solid #34537f;background:#152945;color:#eaf2ff;text-decoration:none}input{padding:10px;border-radius:10px;background:#091426;color:#fff;border:1px solid #34537f;width:100%}@media(max-width:600px){.wrap{padding:12px}}</style></head><body><div class=top><b>🛰 NavIC GPS Bridge</b><span id=live>● CONNECTING</span></div><main class=wrap><div class=grid><div class=card><div class=label>Position</div><div id=pos class=value>Waiting…</div></div><div class=card><div class=label>Fix</div><div id=fix class=value>—</div></div><div class=card><div class=label>Satellites</div><div id=used class=value>—</div></div><div class=card><div class=label>Speed</div><div id=speed class=value>—</div></div><div class=card><div class=label>Altitude</div><div id=alt class=value>—</div></div><div class=card><div class=label>HDOP</div><div id=hdop class=value>—</div></div></div><h3>Alerts</h3><div class=card id=alert>Waiting for GNSS events…</div><h3>Wi-Fi & Device</h3><div class=card id=diag>Loading…</div><h3>Satellites in View</h3><div id=sats class=sats></div><h3>Track Logging</h3><div class=card><div id=track>Loading…</div><div class=actions style="margin-top:12px"><a class=btn href="/api/track.csv">CSV</a><a class=btn href="/api/track.gpx">GPX</a><a class=btn href="/api/track.kml">KML</a><button onclick="fetch('/api/track/clear',{method:'POST'}).then(u)">Clear Track</button></div></div><h3>Firmware Update</h3><div class=card><form id=ota><input type=file name=firmware accept=".bin" required><div class=actions style="margin-top:12px"><button>Upload Firmware</button></div></form><div id=otaStatus></div></div><h3>Latest NMEA</h3><div class=card><pre id=raw></pre></div></main><script>ota.onsubmit=async e=>{e.preventDefault();otaStatus.textContent='Uploading…';let r=await fetch('/api/ota',{method:'POST',body:new FormData(ota)});otaStatus.textContent=await r.text()};async function u(){try{let d=await(await fetch('/api/live')).json();live.textContent=d.data_fresh?'● LIVE · '+d.packets:'● NO DATA';live.className=d.data_fresh?'ok':'bad';fix.textContent=d.fix?'VALID FIX':'NO FIX';fix.className=d.fix?'value ok':'value bad';pos.textContent=d.latitude.toFixed(6)+', '+d.longitude.toFixed(6);used.textContent=d.satellites;speed.textContent=d.speed_kmh.toFixed(1)+' km/h';alt.textContent=d.altitude.toFixed(1)+' m';hdop.textContent=d.hdop||'—';raw.textContent=d.last_nmea;sats.innerHTML=d.satellite_view.map(s=>'<div class=sat><b>'+s.constellation+' '+s.prn+'</b><br>'+s.snr+' dB-Hz<div class=bar><div class=fill style="width:'+Math.min(100,s.snr*2)+'%"></div></div></div>').join('');let x=await(await fetch('/api/diagnostics')).json();diag.textContent='Mode: '+x.wifi_mode+' · IP: '+x.ip+' · Uptime: '+x.uptime_s+'s · Heap: '+x.free_heap+' · Packets: '+x.packets+' · Invalid: '+x.invalid+' · Clients: '+x.clients;let a=await(await fetch('/api/alerts')).json();alert.textContent=a.message+' · Events: '+a.count;let t=await(await fetch('/api/track')).json();track.textContent=t.points+' points · Rolling buffer '+t.capacity}catch(e){live.textContent='● DISCONNECTED';live.className='bad'}}setInterval(u,1000);u()</script></body></html>)HTML";}
void live(){auto&d=nmea.data();JsonDocument j;j["fix"]=d.fix;j["latitude"]=d.latitude;j["longitude"]=d.longitude;j["altitude"]=d.altitude;j["speed_kmh"]=d.speedKmh;j["satellites"]=d.satellites;j["hdop"]=d.hdop;j["last_nmea"]=d.lastSentence;j["packets"]=packets;j["data_fresh"]=millis()-lastDataMs<3000;auto a=j["satellite_view"].to<JsonArray>();for(int i=0;i<nmea.satelliteCount();i++){auto&s=nmea.satellites()[i];auto o=a.add<JsonObject>();o["constellation"]=s.constellation;o["prn"]=s.prn;o["snr"]=s.snr;}String b;serializeJson(j,b);web.send(200,"application/json",b);}
void diagnostics(){JsonDocument j;j["uptime_s"]=millis()/1000;j["free_heap"]=ESP.getFreeHeap();j["packets"]=packets;j["invalid"]=invalid;j["wifi_mode"]=wifiMode;j["ip"]=wifiMode=="AP"?WiFi.softAPIP().toString():WiFi.localIP().toString();int c=0;for(auto&x:clients)if(x&&x.connected())c++;j["clients"]=c;String b;serializeJson(j,b);web.send(200,"application/json",b);}
void alerts(){auto&e=events.last();JsonDocument j;j["message"]=e.message;j["timestamp_ms"]=e.timestamp;j["count"]=events.count();String b;serializeJson(j,b);web.send(200,"application/json",b);}
void trackJson(){JsonDocument j;j["points"]=logger.size();j["capacity"]=GnssLogger::MAX_POINTS;String b;serializeJson(j,b);web.send(200,"application/json",b);}
void trackCsv(){String out="timestamp_ms,latitude,longitude,altitude_m,speed_kmh\n";for(size_t i=0;i<logger.size();i++){auto&p=logger.at(i);out+=String(p.timestamp)+","+String(p.lat,7)+","+String(p.lon,7)+","+String(p.altitude,2)+","+String(p.speedKmh,2)+"\n";}web.sendHeader("Content-Disposition","attachment; filename=navic-gps-track.csv");web.send(200,"text/csv",out);}void trackGpx(){web.send(200,"application/gpx+xml",trackToGpx(logger));}void trackKml(){web.send(200,"application/vnd.google-earth.kml+xml",trackToKml(logger));}
void otaDone(){web.send(200,"text/plain",Update.hasError()?"OTA failed":"OTA successful. Restarting…");delay(300);if(!Update.hasError())ESP.restart();}void otaUpload(){HTTPUpload&u=web.upload();if(u.status==UPLOAD_FILE_START)Update.begin(UPDATE_SIZE_UNKNOWN);else if(u.status==UPLOAD_FILE_WRITE){if(Update.write(u.buf,u.currentSize)!=u.currentSize)Update.abort();}else if(u.status==UPLOAD_FILE_END)Update.end(true);}
void setup(){Serial.begin(115200);settings.begin();auto&c=settings.get();GNSS.begin(c.gnssBaud,SERIAL_8N1,16,17);GPSOut.begin(c.gpsOutBaud,SERIAL_8N1,-1,18);WiFi.mode(WIFI_AP);WiFi.softAP("NavIC-GPS-Bridge","navicgps");tcp.begin();web.on("/",[]{web.send(200,"text/html",page());});web.on("/api/live",live);web.on("/api/diagnostics",diagnostics);web.on("/api/alerts",alerts);web.on("/api/track",trackJson);web.on("/api/track.csv",trackCsv);web.on("/api/track.gpx",trackGpx);web.on("/api/track.kml",trackKml);web.on("/api/track/clear",HTTP_POST,[]{logger.clear();web.send(200,"application/json","{\"ok\":true}");});web.on("/api/ota",HTTP_POST,otaDone,otaUpload);web.begin();}
void loop(){web.handleClient();WiFiClient incoming=tcp.available();if(incoming)for(auto&c:clients)if(!c||!c.connected()){c=incoming;break;}while(GNSS.available()){String l=GNSS.readStringUntil('\n');l.trim();if(!l.length())continue;if(!nmea.process(l)){invalid++;continue;}packets++;lastDataMs=millis();auto&d=nmea.data();logger.add(d.latitude,d.longitude,d.altitude,d.speedKmh,millis());events.update(d,true,millis());String o=nmea.gpsCompatible(l);GPSOut.println(o);for(auto&c:clients)if(c&&c.connected())c.println(o);}events.update(nmea.data(),millis()-lastDataMs<3000,millis());}